// One output item per lead, shaped for the Leads tab. Returns [] when
// there's nothing to sweep (alwaysOutputData on the query means we can get
// a single empty item through) -- downstream nodes then simply don't run.
const rows = $input.all().map(i => i.json).filter(r => r && r.phone);

const out = [];
for (const r of rows) {
  let ctx = r.current_context;
  if (typeof ctx === 'string') { try { ctx = JSON.parse(ctx); } catch (e) { ctx = {}; } }
  ctx = ctx || {};
  const f = ctx.fields || {};

  const isPartner = String(r.current_state || '').indexOf('PARTNER') === 0;
  const val = (v) => (v === null || v === undefined || v === '') ? '' : String(v);

  // Everything actually captured, so sales can see the real substance even
  // for fields that have no dedicated column below.
  const captured = {};
  for (const k of Object.keys(f)) {
    if (f[k] !== null && f[k] !== undefined && f[k] !== '' && k !== 'phone') captured[k] = f[k];
  }
  const capturedCount = Object.keys(captured).length;

  const stageLabel = {
    QUOTE_COLLECTING: 'Quote - answering questions',
    QUOTE_CONFIRMING: 'Quote - reached confirmation, never confirmed',
    PARTNER_COLLECTING: 'Partner - answering questions',
    PARTNER_CONFIRMING: 'Partner - reached confirmation, never confirmed'
  }[r.current_state] || r.current_state;

  out.push({ json: {
    phone: r.phone,
    enquiry_type: isPartner ? 'Partner' : 'Quote',
    stage: stageLabel,
    name: val(f.customer_name || f.contact_name),
    destination_country: val(f.destination_country),
    weight_kg: val(f.weight_kg),
    volume_cbm: val(f.volume_cbm),
    cargo_category: val(f.cargo_category),
    shipping_method: val(f.shipping_method),
    business_name: val(f.business_name),
    email: val(f.email),
    based_in: [val(f.city), val(f.country)].filter(Boolean).join(', '),
    details_captured: capturedCount ? JSON.stringify(captured) : '',
    fields_captured_count: capturedCount,
    first_seen: r.created_at,
    last_activity: r.updated_at,
    hours_since_last_activity: Math.round((Number(r.minutes_idle) || 0) / 6) / 10,
    lead_status: capturedCount > 0 ? 'Abandoned - has details, follow up' : 'Abandoned - no details captured',
    follow_up_status: '',
    owner: '',
    internal_notes: ''
  } });
}
return out;
